export const QUESTIONS_PER_LEVEL = 25;

export function shuffleQuestionsArray(array = []) {
  const copy = [...array];
  for (let i = copy.length - 1; i > 0; i -= 1) {
    const j = Math.floor(Math.random() * (i + 1));
    [copy[i], copy[j]] = [copy[j], copy[i]];
  }
  return copy;
}

export function getSubjectLevels(subjectId) {
  const allQuestions = QUESTION_BANK[subjectId] || [];
  const totalCount = allQuestions.length;
  const count = Math.max(1, Math.ceil(totalCount / QUESTIONS_PER_LEVEL));
  return Array.from({ length: count }, (_, index) => {
    const start = index * QUESTIONS_PER_LEVEL;
    const questionsPool = allQuestions.slice(start, start + QUESTIONS_PER_LEVEL);
    const number = index + 1;
    const difficultyLabel = number > Math.ceil(count * 0.66) ? 'مستوى متقدم' : number > Math.ceil(count * 0.33) ? 'مستوى متوسط' : 'مستوى تأسيسي';
    const badgeColor = difficultyLabel === 'مستوى متقدم' ? 'bg-purple-50 text-purple-700 border-purple-200' : difficultyLabel === 'مستوى متوسط' ? 'bg-indigo-50 text-indigo-700 border-indigo-200' : 'bg-emerald-50 text-emerald-700 border-emerald-200';
    return { levelNumber: number, id: String(number), title: `المستوى ${number}`, difficultyLabel, badgeColor, questionCount: questionsPool.length, rangeLabel: `الأسئلة ${start + 1} – ${start + questionsPool.length}`, questionsPool };
  });
}

export const QUESTION_COUNTS = Object.freeze(Object.fromEntries(Object.entries(QUESTION_BANK).map(([subject, questions]) => [subject, questions.length])));
export const TOTAL_QUESTION_COUNT = Object.values(QUESTION_COUNTS).reduce((sum, count) => sum + count, 0);
